"""Authored explanations of mechanisms in seminars and assignments, not submitted solutions."""
from copy import deepcopy


def extend(lessons, topics, questions):
    lessons.append(dict(id=6,title='Сегментация и Segment Anything',short='Сегментация и SAM',tag='MASKS & PROMPTS',description='Маски, U-Net, подсказки SAM, псевдоразметка и честная оценка.',color='#81a9b3'))
    specs=[]
    def S(lesson,key,title,path,cells,definition,mechanism,example,trap,formula,reason,criteria):
        source=dict(path=path,cells=cells)
        if not path.endswith('.ipynb'):source['document']=True
        specs.append(dict(id=key,lesson=lesson,title=title,source=source,definition=definition,detail=mechanism,
            example=example,trap=trap,formula=formula,diagrams=[],supplemental=True,
            mathNotes=f'{mechanism}\n\n$$ {formula} $$\n\n**Проверка на числах.** {example}',
            walkthrough=dict(title=title+' на маленьком примере',given=example,steps=[dict(title='Что вычисляем',text=definition),dict(title='Почему это работает',text=mechanism),dict(title='Проверяем ограничение',text=trap)],conclusion=reason,source=deepcopy(source))))
        base=dict(lesson=lesson,topic=key,level='reason',type='open',source=deepcopy(source),collection='materials')
        def Q(suffix,prompt,answer,rubric):questions.append(dict(base,id=key+'-'+suffix,prompt=prompt,answer=answer,example=example,rubric=rubric))
        Q('mechanism','Объясните по шагам: '+title+'.',definition+'\n\n'+mechanism,criteria)
        Q('failure','Разберите ограничение: '+trap,reason+'\n\n'+mechanism,criteria)
        Q('case','Разберите пример и обоснуйте результат: '+example,example+'\n\n'+mechanism,criteria)
        Q('transfer',reason+' Как это связано с темой «'+title+'»?',definition+'\n\n'+mechanism,criteria)

